    'Le musée imaginaire': g => quatre(g, (x, y, i) => g.tag(x, y + 2, ['la foule', 'l\'attente', 'la tempête', 'la rencontre'][i], {s: 8.5})).n(1, 'chaque groupe tire une carte-thème et crée 3 tableaux vivants qui la racontent'),
